package com.bank.batch;

import java.math.BigDecimal;

// LIBRARY-STYLE helper: it NEVER calls System.exit. It signals problems by
// throwing, leaving the decision to terminate entirely to the application.
public class SettlementValidator {
    public void validate(String fromId, String toId, BigDecimal amount) {
        if (fromId == null || toId == null)
            throw new IllegalArgumentException("Account ids must not be null");
        if (amount == null || amount.signum() <= 0)
            throw new IllegalArgumentException("Amount must be positive, was " + amount);
        // Note: NO System.exit here. A helper has no right to kill the process.
    }
}
