package com.bank.batch;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

public class SettlementBatch {
    private static final Logger log = Logger.getLogger(SettlementBatch.class.getName());
    private final SettlementValidator validator = new SettlementValidator();
    private final Map<String, Account> accounts;
    private int rejected = 0;

    public SettlementBatch(Map<String, Account> accounts) { this.accounts = accounts; }

    // Processes every transfer and returns the number of rejected items.
    // It does NOT exit — it returns a result so main can decide the exit code.
    public int process(List<String[]> transfers) {
        for (String[] t : transfers) {
            String fromId = t[0], toId = t[1];
            BigDecimal amount = new BigDecimal(t[2]);
            try {
                validator.validate(fromId, toId, amount);
                accounts.get(fromId).debit(amount);
                accounts.get(toId).credit(amount);
                log.info(() -> "Settled " + amount + " from " + fromId + " to " + toId);
            } catch (RuntimeException e) {
                rejected++;
                log.warning(() -> "Rejected " + fromId + "→" + toId + ": " + e.getMessage());
            }
        }
        return rejected;
    }
}
