package com.bank.batch;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SettlementBatchDemo {
    private static final Logger log = Logger.getLogger(SettlementBatchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Shutdown hook: THIS runs during System.exit — the right place for
        // last-chance cleanup like flushing the audit log.
        Runtime.getRuntime().addShutdownHook(new Thread(() ->
                log.info("Shutdown hook: audit log flushed to disk")));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        Map<String, Account> accounts = new HashMap<>();
        accounts.put(rajesh.getAccountId(), rajesh);
        accounts.put(priya.getAccountId(), priya);

        List<String[]> transfers = List.of(
                new String[]{"SAV2001", "CUR3001", "50000"},   // valid
                new String[]{"SAV2001", "CUR3001", "-10"},      // invalid amount → rejected
                new String[]{"CUR3001", "SAV2001", "20000"}     // valid
        );

        SettlementBatch batch = new SettlementBatch(accounts);
        int rejected = batch.process(transfers);

        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());
        log.info(() -> "Rejected count: " + rejected);

        // main — the ONLY place with authority to end the process — picks the code.
        int exitCode = (rejected == 0) ? 0 : 2; // 0 all good, 2 = some rejected
        log.info(() -> "Exiting with code " + exitCode + " (0=success, 2=partial reject)");
        System.exit(exitCode); // shutdown hook runs; any running finally would NOT
    }
}
